function calcularTotal() {
  let total = 0;
  for (const fila of document.querySelectorAll('.linea')) {
    const campo = c => fila.querySelector(c);
    const cantidad = numero(campo('.cantidad').value);
    const precio = numero(campo('.precio').value);
    const importe = cantidad * precio;
    campo('.importe').textContent = euros.format(importe);
    total += importe;
  }
  $('#t-total').textContent = euros.format(total);
}
